'use client';

import React, { useState } from 'react';
import { FadeInUp } from '@/components/FadeInUp';
import { HeadingPill } from '@/components/ui/HeadingPill';

export default function ContactPage() {
  const [submitted, setSubmitted] = useState(false);
  const [selectedServices, setSelectedServices] = useState<{ [key: string]: boolean }>({
    Development: false,
    'UI/UX Design': false,
    Branding: false,
    Marketing: false,
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    message: '',
  });

  const toggleService = (serviceKey: string) => {
    setSelectedServices((prev) => ({
      ...prev,
      [serviceKey]: !prev[serviceKey],
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const activeServices = Object.keys(selectedServices).filter(
      (key) => selectedServices[key]
    );

    try {
      const res = await fetch("/api/contact", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ...formData,
          services: activeServices,
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to send message. Please try again.");
      }

      setSubmitted(true);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const servicesList = ['Development', 'UI/UX Design', 'Branding', 'Marketing'];

  const isFormValid =
    formData.name.trim() !== '' &&
    formData.phone.trim() !== '' &&
    formData.email.trim() !== '' &&
    formData.message.trim() !== '';

  return (
    <div id="contact" className="min-h-screen bg-white flex flex-col justify-between pt-24 pb-12 font-paragraph relative">
      {/* Background Gradient exactly for the Banner Section */}
      <div className="absolute top-0 left-0 w-full h-[600px] bg-[linear-gradient(180deg,#dbeafe_0%,#ffffff_100%)] pointer-events-none z-0" />
      
      <div className="w-[90%] xl:w-[82%] max-w-[1260px] mx-auto py-12 relative z-10">
        {/* Banner Section */}
        <FadeInUp>
          <div className="mb-12 text-center flex flex-col items-center">
            <HeadingPill text="Get In Touch" />
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-normal tracking-tight text-cs-ink leading-tight font-display">
              Contact <span className="text-brand-default">Us.</span>
            </h1>
            <p className="mt-4 text-sm md:text-base text-cs-ink-muted max-w-2xl leading-relaxed text-center">
              At Cueserve, we offer a full range of creative and digital services designed to help brands stand out and succeed in a fast-evolving digital world.
            </p>
          </div>
        </FadeInUp>

        {/* Contact Layout Card */}
        <FadeInUp>
          <div className="bg-brand-default rounded-[32px] md:rounded-[40px] overflow-hidden shadow-lg grid grid-cols-1 lg:grid-cols-2 p-6 md:p-10 lg:p-12 gap-8 lg:gap-16 items-start">
            
            {/* Left Panel */}
            <div className="text-white flex flex-col h-full w-full pt-1">
              <div className="mb-8">
                <h2 className="text-3xl md:text-4xl lg:text-5xl font-display font-medium tracking-tight">Fill This Form.</h2>
              </div>
              
              <div className="rounded-[24px] md:rounded-[32px] overflow-hidden w-full aspect-[4/3] md:aspect-[16/10] lg:aspect-auto lg:h-[400px] relative mt-auto">
                <img 
                   src="/assets/images/contact/Contact-Team.jpg" 
                  alt="Our Team" 
                  className="w-full h-full object-cover"
                />
              </div>
            </div>

            {/* Right Panel (Form) */}
            <div className={"text-white w-full " + (submitted ? "lg:mt-[88px]" : "")}>
              {!submitted ? (
                <form onSubmit={handleSubmit} className="space-y-8">
                  {/* Services Checklist */}
                  <div>
                    <div className="text-base md:text-lg font-medium mb-4">
                      Tell us about your projects*
                    </div>
                    <div className="flex flex-wrap gap-2 md:gap-3">
                      {servicesList.map((service) => {
                        const isChecked = !!selectedServices[service];
                        return (
                          <button
                            key={service}
                            type="button"
                            onClick={() => toggleService(service)}
                            className={"px-5 py-2.5 rounded-full text-xs md:text-sm transition-all duration-200 border " + (isChecked ? 'bg-black text-white border-black shadow-md' : 'bg-white/10 text-white border-transparent hover:bg-white/20')}
                          >
                            {service}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  {/* Form Fields */}
                  <div className="space-y-6 pt-2">
                    <div>
                      <input
                        type="text"
                        name="name"
                        placeholder="Your Name *"
                        required
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        className="w-full py-3 bg-transparent border-b border-white/30 text-white placeholder-white/70 focus:outline-none focus:border-white transition-all text-sm md:text-base"
                      />
                    </div>
                    
                    <div>
                      <input
                        type="tel"
                        name="phone"
                        placeholder="Phone Number *"
                        required
                        value={formData.phone}
                        onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                        className="w-full py-3 bg-transparent border-b border-white/30 text-white placeholder-white/70 focus:outline-none focus:border-white transition-all text-sm md:text-base"
                      />
                    </div>

                    <div>
                      <input
                        type="email"
                        name="email"
                        placeholder="Email *"
                        required
                        value={formData.email}
                        onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                        className="w-full py-3 bg-transparent border-b border-white/30 text-white placeholder-white/70 focus:outline-none focus:border-white transition-all text-sm md:text-base"
                      />
                    </div>

                    <div>
                      <textarea
                        name="message"
                        placeholder="Message *"
                        rows={2}
                        required
                        value={formData.message}
                        onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                        className="w-full py-3 bg-transparent border-b border-white/30 text-white placeholder-white/70 focus:outline-none focus:border-white transition-all text-sm md:text-base resize-none"
                      />
                    </div>
                  </div>

                  {/* Error Notification */}
                  {error && (
                    <div className="text-red-200 text-xs md:text-sm font-medium bg-red-950/40 p-3 rounded-[16px] border border-red-500/20">
                      {error}
                    </div>
                  )}

                  {/* Submit */}
                  <div className="pt-4">
                    <button
                      type="submit"
                      disabled={!isFormValid || loading}
                      className={"py-3 md:py-4 px-6 md:px-8 rounded-full font-semibold text-sm transition-all duration-300 " + (isFormValid && !loading ? 'bg-white text-brand-default hover:bg-gray-100 cursor-pointer shadow-lg' : 'bg-white/50 text-brand-default cursor-not-allowed')}
                    >
                      {loading ? 'Sending...' : 'Get In Touch'}
                    </button>
                  </div>
                </form>
              ) : (
                <div className="flex flex-col items-center justify-center min-h-[380px] text-center p-6 bg-white/10 rounded-[24px]">
                  <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-6 text-brand-default text-2xl font-bold">
                    Γ£ô
                  </div>
                  <h3 className="text-2xl font-bold text-white mb-2">Thank you, {formData.name}!</h3>
                  <p className="text-white/80 max-w-md leading-relaxed text-sm">
                    We&apos;ve successfully received your message and will get back to you shortly at <strong>{formData.email}</strong>.
                  </p>
                </div>
              )}
            </div>
          </div>
        </FadeInUp>
      </div>
    </div>
  );
}

"use client";

import React, { useRef, useState } from "react";
import { gsap, ScrollTrigger, useGSAP } from "@/lib/gsap";

export function AboutMediaSection() {
  const sectionRef = useRef<HTMLDivElement>(null);
  const videoPinContainerRef = useRef<HTMLDivElement>(null);
  const videoWrapperRef = useRef<HTMLDivElement>(null);
  const statsWrapperRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(true);

  const togglePlay = () => {
    if (!videoRef.current) return;
    if (videoRef.current.paused) {
      videoRef.current.play();
      setIsPlaying(true);
    } else {
      videoRef.current.pause();
      setIsPlaying(false);
    }
  };

  useGSAP(
    () => {
      const mm = gsap.matchMedia();

      mm.add("(min-width: 1024px)", () => {
        if (!videoPinContainerRef.current || !videoWrapperRef.current || !statsWrapperRef.current) return;

        const tl = gsap.timeline({
          scrollTrigger: {
            trigger: sectionRef.current, // Pin the top-level section right below the floating navbar so the entire section and footer below are cleanly spaced
            start: "top top+=100",
            end: "+=800",
            scrub: 1.5,
            pin: true,
            pinSpacing: true,
          },
        });

        // STAGE 1: Right stats box stays right at its horizontal place, glides straight UP (y: -420), and disappears cleanly
        tl.to(
          statsWrapperRef.current,
          {
            y: -420,
            opacity: 0,
            scale: 0.9,
            duration: 1.2,
            ease: "power2.inOut",
          },
          0
        );

        // Once the right box has gone up and disappeared completely at 1.2s, instantly hide its layout box
        // so it never shifts sideways while going up and never pushes the video sideways when zooming
        tl.set(
          statsWrapperRef.current,
          {
            display: "none",
          },
          1.2
        );

        // STAGE 2: After the right box went up and disappeared, left video zooms wide across 100% navbar width
        tl.to(
          videoWrapperRef.current,
          {
            width: "100%",
            height: "clamp(480px, 80vh, 800px)",
            y: -40,
            duration: 2.0,
            ease: "power3.inOut",
          },
          1.2
        );
      });

      return () => mm.revert();
    },
    { scope: sectionRef }
  );

  return (
    <>
      <section
        ref={sectionRef}
        className="relative z-30 bg-white pt-12 sm:pt-16 xl:pt-24 pb-8 sm:pb-10 lg:pb-20 xl:pb-24 min-h-0 lg:min-h-[680px] xl:min-h-[750px]"
      >
        {/* Exact navbar width container: w-[90%] xl:w-[82%] max-w-[1260px] mx-auto */}
        <div ref={videoPinContainerRef} className="w-[90%] xl:w-[82%] max-w-[1260px] mx-auto">

          {/* Side-by-side resting layout: Both reduced equally (46% each) with a clean gap between, and EXACT SAME height (250px) */}
          <div className="flex flex-col-reverse lg:flex-row items-center justify-between gap-8 lg:gap-[6%] w-full">

            {/* Left Container: Video Format Card (Exact same resting height as right box: h-[200px]) */}
            <div
              ref={videoWrapperRef}
              className="w-full lg:w-[47%] h-[240px] sm:h-[300px] md:h-[360px] lg:h-[280px] rounded-[32px] sm:rounded-[38px] overflow-hidden relative bg-cs-ink/5 border border-cs-border shrink-0 flex items-center justify-center group"
            >
              {/* Background Video */}
              <video
                ref={videoRef}
                src="/video1.mp4"
                autoPlay
                loop
                muted
                playsInline
                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
              />

              {/* Subtle Gradient Overlay for contrast and controls */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent pointer-events-none" />

              {/* Pause / Play Glassmorphic Button */}
              <button
                type="button"
                onClick={togglePlay}
                aria-label={isPlaying ? "Pause video" : "Play video"}
                className="absolute bottom-5 left-5 sm:bottom-6 sm:left-6 z-10 w-11 h-11 sm:w-12 sm:h-12 rounded-full bg-white/40 border border-white/60 flex items-center justify-center text-white hover:bg-white/50 hover:scale-110 transition-all"
              >
                {isPlaying ? (
                  /* Pause Icon (||) */
                  <svg className="w-4 h-4 fill-current" viewBox="0 0 16 16">
                    <path d="M5.5 3.5A1.5 1.5 0 0 1 7 5v6a1.5 1.5 0 0 1-3 0V5a1.5 1.5 0 0 1 1.5-1.5zm5 0A1.5 1.5 0 0 1 12 5v6a1.5 1.5 0 0 1-3 0V5a1.5 1.5 0 0 1 1.5-1.5z" />
                  </svg>
                ) : (
                  /* Play Icon (Triangle) */
                  <svg className="w-4 h-4 fill-current ml-0.5" viewBox="0 0 16 16">
                    <path d="M11.596 8.697l-6.363 3.692c-.54.313-1.233-.066-1.233-.697V4.308c0-.63 1.693-1.01 1.233-.696l6.363 3.692a.802.802 0 0 1 0 1.393z" />
                  </svg>
                )}
              </button>
            </div>

            {/* Right Container: Icon & Metrics Box (Exact same resting height as video: h-[200px]) */}
            <div
              ref={statsWrapperRef}
              className="w-full lg:w-[47%] h-auto rounded-[32px] sm:rounded-[38px] p-5 sm:p-5 border border-[#e2edff] bg-[#F5FAFF] flex flex-col sm:flex-row items-center gap-5 sm:gap-6 justify-between shrink-0"
            >
              {/* Left Icon Box with gradient: linear-gradient(180deg, #0136A2 0%, #266DFB 100%) */}
              <div
                className="w-full aspect-[1/0.8] sm:aspect-auto sm:w-28 sm:h-28 lg:w-[132px] lg:h-[132px] rounded-[24px] sm:rounded-[30px] shrink-0 flex items-center justify-center relative overflow-hidden"
                style={{ background: "linear-gradient(180deg, #0136A2 0%, #266DFB 100%)" }}
              >
                {/* Timer / Clock Icon from public folder */}
                <img
                  src="/timer.png"
                  alt="Alarm Timer Icon"
                  className="w-[65%] h-[65%] sm:w-20 sm:h-20 lg:w-24 lg:h-24 object-contain"
                />
              </div>

              {/* Right Side Stats Columns */}
              <div className="flex flex-1 items-start sm:items-center justify-around gap-4 sm:gap-6 w-full px-2 sm:px-0 sm:pl-2 pt-2 sm:pt-0">
                {/* Stat 1: 96% Positive Feedback */}
                <div className="flex flex-col items-center text-center sm:items-start sm:text-left">
                  <span className="text-4xl sm:text-h3 font-display font-normal sm:font-medium text-cs-ink tracking-tight leading-none mb-1.5 sm:mb-2.5">
                    96%
                  </span>
                  <span className="font-paragraph font-light text-[10px] sm:text-base text-neutral-900 leading-[1.3] sm:leading-none uppercase w-[120px] sm:w-[147px]">
                    Positive Feedback<br />From Clients
