                    <p className="font-paragraph font-light text-base md:text-[15px] lg:text-2xl text-cs-ink leading-relaxed">{next.quote}</p>
                  </div>
                </div>
              </motion.div>

              {/* Active Deck Card (Flipped / Active) */}
              <motion.div
                key={`active-${currentIndex}`}
                custom={direction}
